/**
 * Mock authentication and session handling.
 *
 * The accounts are seeded and the password is public, so this is not a
 * production identity system - but the credentials are not stored in
 * plaintext, the session token is generated by the crypto module, and an
 * unknown account is indistinguishable from a wrong password.
 */
import { randomBytes } from 'node:crypto';
import { verifyPassword, hashPassword } from '../passwords.js';

// Verified against when the account does not exist, so that a missing account
// and a wrong password cost the same time and cannot be told apart.
const DECOY = hashPassword('no-such-account');

/**
 * Create the session store.
 *
 * Sessions live in memory: there is nothing to provision, and a restart
 * logging everyone out is an acceptable trade for a mock. The first item on
 * the "what next" list is a persistent store.
 *
 * @param {{ ttlMs: number }} options
 */
export function createSessionStore({ ttlMs }) {
  /** @type {Map<string, { coordinatorId: number, lastSeen: number }>} */
  const sessions = new Map();

  return {
    /**
     * @returns {{ kind: 'ok', token: string, coordinator: object } | { kind: 'invalid_credentials' }}
     */
    login(statements, { email, password }) {
      const normalised = String(email ?? '').trim().toLowerCase();
      const coordinator = statements.getCoordinatorByEmail.get(normalised);

      const valid = coordinator
        ? verifyPassword(password, coordinator.password_hash, coordinator.password_salt)
        : verifyPassword(password, DECOY.hash, DECOY.salt);

      if (!coordinator || !valid) {
        return { kind: 'invalid_credentials' };
      }

      const token = randomBytes(32).toString('hex');
      sessions.set(token, { coordinatorId: coordinator.id, lastSeen: Date.now() });

      return {
        kind: 'ok',
        token,
        coordinator: { id: coordinator.id, name: coordinator.name, email: coordinator.email },
      };
    },

    /**
     * @returns {object | null} the session, or null when the token is unknown
     *   or has expired
     */
    get(token, now = Date.now()) {
      if (!token) return null;
      const session = sessions.get(token);
      if (!session) return null;

      if (now - session.lastSeen > ttlMs) {
        sessions.delete(token);
        return null;
      }

      session.lastSeen = now;
      return session;
    },

    logout(token) {
      return sessions.delete(token);
    },
  };
}
